Select INV_SET_Category.CategoryName AS ItemCategory, INV_Item.Description As ItemName, INV_Item.InventoryItemStatusCode, Set_UnitOfMeasure.UOMName AS UOM, INV_Item.ListPricePerUnit AS SellingPrice, IsNull(HoldingStock.QtyInHand, 0) As QtyInHand, IsNull(HoldingStock.AveragePrice, 0) AS AveragePrice, IsNull(HoldingStock.GrossAmountHolding, 0) AS GrossAmountHolding, IsNull(ConsumedStock.ConsumedQty, 0) AS ConsumedQty, IsNull(ConsumedStock.GrossAmountConsumed, 0) AS GrossAmountConsumed From INV_Item Inner Join INV_SET_Category ON --INV_Item.CompanyID = INV_SET_Category.CompanyID And INV_Item.ItemTypeID = INV_SET_Category.CategoryID And (INV_SET_Category.CategoryID = @CategoryID OR @CategoryID is null) And (INV_SET_Category.IsInvisibleUponStockReports IS NULL OR INV_SET_Category.IsInvisibleUponStockReports = 0) Inner Join Set_UnitOfMeasure ON INV_Item.PrimaryUOMCode = Set_UnitOfMeasure.UOMID Left Join ( Select INV_StockTransactionDetail.CompanyID, INV_StockTransactionDetail.ItemID, Sum(case SET_DocumentType.TransactionImpact when 'No Impact' then 0 else INV_StockTransactionDetail.TransactionQuantity End) AS QtyInHand, IsNull(AVG(INV_StockTransactionDetail.TransactionCost), 0) AS AveragePrice, (IsNull(Sum(case SET_DocumentType.TransactionImpact when 'No Impact' then 0 else INV_StockTransactionDetail.TransactionQuantity End), 0) * IsNull(AVG(INV_StockTransactionDetail.TransactionCost), 0)) AS GrossAmountHolding from INV_StockTransactionDetail Inner Join INV_StockTransactionHeader ON INV_StockTransactionHeader.CompanyID = INV_StockTransactionDetail.CompanyID And INV_StockTransactionHeader.PeriodID = INV_StockTransactionDetail.PeriodID And INV_StockTransactionHeader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID And INV_StockTransactionHeader.Status = 1 And INV_StockTransactionHeader.IsActive = 1 {StockHeaderFilter}
Inner Join Set_DocumentType On Set_DocumentType.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID And Set_DocumentType.CompanyID = Inv_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = Inv_StockTransactionHeader.PeriodID AND Set_DocumentType.Status = 1 Where INV_StockTransactionDetail.PeriodID = @PeriodID And INV_StockTransactionDetail.Status = 1 And INV_StockTransactionDetail.IsActive = 1
{0}
Group By INV_StockTransactionDetail.CompanyID, INV_StockTransactionDetail.ItemID
) As HoldingStock On --HoldingStock.CompanyID = INV_Item.CompanyID And HoldingStock.ItemID = INV_Item.ItemID
Left Join ( Select StockConsumed.CompanyID, StockConsumed.ItemID, IsNull(Sum(case SET_DocumentType.TransactionImpact when 'No Impact' then 0 else StockConsumed.TransactionQuantity End), 0) * -1 As ConsumedQty, (IsNull(Sum(case SET_DocumentType.TransactionImpact when 'No Impact' then 0 else StockConsumed.TransactionQuantity End), 0) * IsNull(AVG(StockConsumed.TransactionCost), 0) * -1) AS GrossAmountConsumed From INV_StockTransactionDetail AS StockConsumed Inner Join INV_StockTransactionHeader AS StockConsumedH ON StockConsumedH.CompanyID = StockConsumed.CompanyID And StockConsumedH.PeriodID = StockConsumed.PeriodID And StockConsumedH.StockTransactionID = StockConsumed.StockTransactionID And StockConsumedH.Status = 1 And StockConsumedH.IsActive = 1 {StockHeaderConsumedFilter}
Inner Join Set_DocumentType On Set_DocumentType.DocumentTypeID = StockConsumedH.DocumentTypeID And Set_DocumentType.CompanyID = StockConsumedH.CompanyID And Set_DocumentType.PeriodID = StockConsumedH.PeriodID AND Set_DocumentType.Status = 1
Where StockConsumed.PeriodID = @PeriodID And StockConsumed.Status = 1 And StockConsumed.IsActive = 1 And StockConsumed.TransactionQuantity < 0
{0}
Group By StockConsumed.CompanyID, StockConsumed.ItemID ) As ConsumedStock ON --ConsumedStock.CompanyID = INV_Item.CompanyID And ConsumedStock.ItemID = INV_Item.ItemID Where INV_Item.Status = 1 --And INV_Item.CompanyID = @CompanyID

SELECT std.TransactionDetailID,INV_SET_Category.CategoryID as ItemCategoryID, INV_SET_Category.CategoryName, STD.ItemID, INV_Item.Description as ItemDescription, INV_Item.InventoryItemStatusCode ,STD.TransactionUOMID, ISNULL(INV_Item.ListPricePerUnit, 0) AS TransactionCost, INV_StockTransactionHeader.DocumentTypeID, INV_StockTransactionHeader.DocumentNo, STD.TransactionDetailID, STD.IncurredOnID, STD.IsIncurred, IsNull(AR_Set_Customer.CustomerID, -1) CustomerID, AR_Set_Customer.CustomerName, '' as IncurredDescription, SET_UnitofMeasure.UOMName, ISNULL(STD.Remarks,'') as Remarks,ISNUll(STD.OldItemPrice,0) as OldItemPrice, Round(IsNull( ( case isnull(INV_Item.DownloadableFlag,0) when 0 then (select top 1 INV_StockTransactionDetail.NewCost from INV_StockTransactionDetail Inner Join Inv_StockTransactionHeader On Inv_StockTransactionHeader.CompanyID = INV_StockTransactionDetail.CompanyID And Inv_StockTransactionHeader.PeriodID = INV_StockTransactionDetail.PeriodID And Inv_StockTransactionHeader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID Inner Join Set_DocumentType on Set_DocumentType.CompanyID = Inv_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = Inv_StockTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID Inner Join ApplicationMenu On ApplicationMenu.MenuID = Set_DocumentType.MenuID And ApplicationMenu.MenuPath = '/Inventory/Transaction/Stock_frm.aspx' where INV_StockTransactionDetail.ItemID = INV_Item.ItemID and --INV_StockTransactionDetail.CompanyID = INV_Item.CompanyID and NewCost is not null Order By Inv_StockTransactionHeader.DocumentDate desc) else isnull(inv_Item.ListPricePerUnit,0) end ) , 0) * (STD.TransactionQuantity), 0) AS Amount, INV_StockTransactionHeader.StockTransactionID, ISNULL(STD.Comments, '') as Comments, ISNULL(STD.IsDone, 'false') as IsDone, Abs(STD.PrimaryQuantity) as TransactionQuantity2, Cast(Abs(STD.TransactionQuantity) - Abs(isnull( ( Select Sum(INV_StockTransactionDetail.TransactionQuantity) from INV_StockTransactionDetail Where INV_StockTransactionDetail.CompanyID = @CompanyID And INV_StockTransactionDetail.PeriodID = @PeriodID And INV_StockTransactionDetail.Status = 1 AND INV_StockTransactionDetail.SourceDocumentTypeID = INV_StockTransactionHeader.DocumentTypeID And INV_StockTransactionDetail.SourceCode = INV_StockTransactionHeader.DocumentNo And INV_StockTransactionDetail.SourceHeaderID = STD.StockTransactionID And INV_StockTransactionDetail.SourceLineID = STD.TransactionDetailID ), 0)) AS decimal(18, 0)) as TransactionQuantity, ( select IsNull(Sum(Case when Set_DocumentType.TransactionImpact = 'No Impact' then 0 else INV_StockTransactionDetail.TransactionQuantity END), 0) As SumOfQuantityInStock from INV_StockTransactionDetail Inner Join INV_StockTransactionHeader On INV_StockTransactionHeader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID AND INV_StockTransactionHeader.CompanyID = INV_StockTransactionDetail.CompanyID And INV_StockTransactionDetail.PeriodID = INV_StockTransactionHeader.PeriodID Inner Join SET_DocumentType On SET_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID And SET_DocumentType.CompanyID = INV_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = INV_StockTransactionHeader.PeriodID left join Set_Location on Set_Location.LocationID = INV_StockTransactionHeader.LocationID and Set_Location.Isactive = 1 and Set_Location.Status = 1 and Set_Location.IsWareHouse is null where INV_StockTransactionDetail.ItemID = STD.ItemID And INV_StockTransactionDetail.CompanyID = STD.CompanyId And INV_StockTransactionDetail.PeriodID = STD.PeriodID And INV_StockTransactionDetail.Status = 1 And SET_DocumentType.TransactionImpact <> 'No Impact' AND IsNull(INV_StockTransactionHeader.StatusCode, 0) = 1 ) AS CurrentStock ,isnull(INV_Item.DownloadableFlag,0) as DownloadableFlag ,STD.CostCenterID,[SET_CostCenter].CostCenterName ,INV_StockTransactionHeader.CostCenterID as HeaderCCID ,CC.CostCenterName as HeaderCCName ,STD.SourceCode ,STD.SourceHeaderID ,STD.SourceLineID FROM INV_StockTransactionHeader inner join INV_StockTransactionDetail STD on STD.StockTransactionID = INV_StockTransactionHeader.StockTransactionID and STD.CompanyID = INV_StockTransactionHeader.CompanyID and STD.PeriodID = INV_StockTransactionHeader.PeriodID INNER JOIN INV_Item ON INV_Item.ItemID = STD.ItemID --AND INV_Item.CompanyID = STD.CompanyID Inner join Set_DocumentType on Set_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID And Set_DocumentType.CompanyID = INV_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = INV_StockTransactionHeader.PeriodID -- AND Set_DocumentType.DocumentType like 'GIN' LEFT JOIN INV_SET_Category ON INV_Item.ItemTypeID = INV_SET_Category.CategoryID --and INV_Item.CompanyID = INV_SET_Category.CompanyID LEFT JOIN [SET_UnitofMeasure] ON [SET_UnitofMeasure].[UOMID] = STD.[TransactionUOMID] LEFT JOIN [SET_Currency] ON [SET_Currency].[CurrencyID] = STD.[CurrencyID] LEFT JOIN [SET_CostCenter] ON [SET_CostCenter].[CostCenterID] = STD.CostCenterID Left JOIN [SET_CostCenter] CC on CC.CostCenterID= INV_StockTransactionHeader.CostCenterID
LEFT JOIN [SET_Project] ON [SET_Project].[ProjectID] = STD.[ProjectID] LEFT JOIN AR_Set_Customer on AR_Set_Customer.CustomerID = [INV_StockTransactionHeader].BusinessPartnerID --AND AR_Set_Customer.CompanyID = INV_StockTransactionHeader.CompanyID AND AR_Set_Customer.PeriodID = INV_StockTransactionHeader.PeriodID
Where STD.Status = 1 ANd STD.CompanyID = @CompanyID ANd STD.PeriodID = @PeriodID AND INV_StockTransactionHeader.StatusCode = 1 --and std.Isdone = 1 {0}

Select *, ROW_NUMBER() OVER (ORDER BY tab.DocumentNo desc) AS 'Row' from ( SELECT Distinct -- SAL_DispatchVehicleInformation.Chassis --,SAL_DispatchVehicleInformation.Engine --, [INV_StockTransactionHeader].[CompanyID] , [INV_StockTransactionHeader].[PeriodID] , [INV_StockTransactionHeader].[StockTransactionID] , [INV_StockTransactionHeader].[DocumentTypeID] , [INV_StockTransactionHeader].[DocumentNo] , [INV_StockTransactionHeader].[DocumentDate] , [INV_StockTransactionHeader].[Comments] , [INV_StockTransactionHeader].[Status] , [INV_StockTransactionHeader].[CreatedBy] , [INV_StockTransactionHeader].[CreateDate] , [INV_StockTransactionHeader].[UpdatedBy] , [INV_StockTransactionHeader].[UpdateDate] , [INV_StockTransactionHeader].[CreatedByValue] , [INV_StockTransactionHeader].[UpdatedByValue] , [INV_StockTransactionHeader].StatusCode , [INV_StockTransactionHeader].[IsActive] , [SET_DocumentType].[DocumentType] FROM [INV_StockTransactionHeader] INNER JOIN [SET_DocumentType] ON [SET_DocumentType].[DocumentTypeID] = [INV_StockTransactionHeader].[DocumentTypeID] AND [SET_DocumentType].[Status] = 1 AND [SET_DocumentType].[PeriodID] = [INV_StockTransactionHeader].[PeriodID] AND [SET_DocumentType].[CompanyID] = [INV_StockTransactionHeader].[CompanyID] INNER JOIN INV_StockTransactionDetail on INV_StockTransactionDetail.StockTransactionID = INV_StockTransactionHeader.StockTransactionID AND INV_StockTransactionDetail.CompanyID = INV_StockTransactionHeader.CompanyID AND INV_StockTransactionDetail.PeriodID = INV_StockTransactionHeader.PeriodID
left join SAL_DispatchVehicleInformation on SAL_DispatchVehicleInformation.StockHeaderID = INV_StockTransactionDetail.StockTransactionID and SAL_DispatchVehicleInformation.StockDetailID = INV_StockTransactionDetail.TransactionDetailID and SAL_DispatchVehicleInformation.CompanyID = INV_StockTransactionDetail.CompanyID and SAL_DispatchVehicleInformation.PeriodID = INV_StockTransactionDetail.PeriodID
inner join Set_PeriodCustom on [INV_StockTransactionHeader].DocumentDate between Set_PeriodCustom.StartDate and Set_PeriodCustom.EndDate and Set_PeriodCustom.Status = 1 and SET_PeriodCustom.FiscalID = @CurrentFiscalID
-- where [INV_StockTransactionHeader].CompanyID = @CompanyID -- and [INV_StockTransactionHeader].PeriodID = @PeriodID {wherefilter}
) as tab

Select *,(ISNULL(ExpectedQuantity,0)-ActualQuantity) as DifferenceInPcs from ( Select INV_StockTransactionHeader.StockTransactionID,INV_StockTransactionHeader.LocationID,INV_StockTransactionHeader.StatusCode ,INV_StockTransactionHeader.BusinessPartnerID,INV_StockTransactionHeader.DocumentDate,INV_StockTransactionHeader.DocumentNo ,INV_StockTransactionHeader.DocumentTypeID,INV_StockTransactionHeader.Comments ,abs(INV_StockTransactionDetail.TransactionQuantity) as ActualQuantity,INV_StockTransactionDetail.TransactionCost as Rate,INV_StockTransactionDetail.TransactionUOMID ,INV_StockTransactionDetail.SourceHeaderID,INV_StockTransactionDetail.SourceCode,INV_StockTransactionDetail.SourceDocumentTypeID,INV_StockTransactionDetail.SourceLineID ,INV_Item.Description as FinishItemDescription,INV_Item.ITemID as FinishItemID ,INV_SET_Category.CategoryID as FinishCategoryID, INV_SET_Category.CategoryName as FinishCategoryName,SET_ItemCatalog.ItemCatalogID as FinishCatalogID ,SET_ItemCatalog.Description as FinishCatalogName,INV_StockTransactionDetail.Amount as GrossAmount,INV_StockTransactionDetail.NetAmount ,'' as ProductLine,0 as BaseAmount,Convert(bit,0) as IsSalesTaxExempted, null SalesTaxAmount,Convert(bit,0) as IsExciseDutyExempted, null ExciseDutyAmount ,Convert(bit,0) as IsFEDExempted, null FEDAmount, null SalesTaxAmountA,0 as ItemUnitQuantity, ( select IsNull(Sum(Case when Set_DocumentType.TransactionImpact = 'No Impact' then 0 else CurrentStockDetail.TransactionQuantity END), 0) As SumOfQuantityInStock from INV_StockTransactionDetail CurrentStockDetail Inner Join INV_StockTransactionHeader CurrentStockHeader On CurrentStockHeader.StockTransactionID = CurrentStockDetail.StockTransactionID AND CurrentStockHeader.CompanyID = CurrentStockDetail.CompanyID And CurrentStockHeader.PeriodID = CurrentStockDetail.PeriodID Inner Join SET_DocumentType On SET_DocumentType.DocumentTypeID = CurrentStockHeader.DocumentTypeID And SET_DocumentType.CompanyID = CurrentStockHeader.CompanyID And Set_DocumentType.PeriodID = CurrentStockHeader.PeriodID where CurrentStockDetail.ItemID = INV_Item.ItemID And CurrentStockDetail.CompanyID = @CompanyID And CurrentStockDetail.PeriodID = @PeriodID And INV_StockTransactionDetail.Status = 1 And SET_DocumentType.TransactionImpact <> 'No Impact' AND (isnull(INV_StockTransactionHeader.LocationID,CurrentStockDetail.LocationID) =isnull(INV_StockTransactionHeader.LocationID,INV_StockTransactionDetail.LocationID))
) + Abs(INV_StockTransactionDetail.TransactionQuantity) as CurrentStock ,INV_Item.ItemID,INV_Item.Description,INV_SET_Category.CategoryID as ItemCategoryID,INV_SET_Category.CategoryName ,SET_ItemCatalog.ItemCatalogID as CatalogID , SET_ItemCatalog.Description as CatalogName,SET_UnitofMeasure.UOMID as ItemUnitID,UOMName,null as BatchId ,'' as Batch,null as ColorID,'' as ColorName,(Round(sourcedetail.TransactionQuantity/sourceitem.UnitWeight,2)) as ExpectedQuantity ,INV_Item.UnitWeight,abs(sourcedetail.TransactionQuantity) as IssuedQty,null as DOQty,'' as Action, null as BalanceQty ,INV_StockTransactionHeader.StockTransactionID as OrderID,INV_StockTransactionDetail.TransactionDetailID as OrderDetailID ,abs(INV_StockTransactionDetail.TransactionQuantity) as Quantity,Convert(bit,0) as Inclusive,null as Wastage ,INV_StockTransactionDetail.PackTypeID,Fabrics_PackType.PackType,INV_StockTransactionDetail.NoOfPackages from INV_StockTransactionHeader
inner join SET_DocumentType on SET_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID and SET_DocumentType.DocumentType like '%Material%Issuance%' inner join INV_StockTransactionDetail on INV_StockTransactionDetail.StockTransactionID = INV_StockTransactionHeader.StockTransactionID inner join INV_Item on INV_Item.ItemID =INV_StockTransactionDetail.ItemID inner join INV_SET_Category on INV_SET_Category.CategoryID = INV_ITem.ItemTypeID left join SET_ItemCatalog on SET_ItemCatalog.ItemCatalogID = INV_ITem.ItemCatalogGroupID
left join INV_StockTransactionHeader sourceheader on sourceheader.StockTransactionID = INV_StockTransactionDetail.SourceHeaderID and sourceheader.DocumentNo = INV_StockTransactionDetail.SourceCode and sourceheader.DocumentTypeID = INV_StockTransactionDetail.SourceDocumentTypeID
left join INV_StockTransactionDetail sourcedetail on sourcedetail.StockTransactionID = sourceheader.StockTransactionID left join INV_Item sourceitem on sourceitem.ItemID = sourcedetail.ItemID left join INV_SET_Category sourcecategory on sourcecategory.CategoryID = sourceitem.ItemTypeID left join SET_ItemCatalog sourcecatalog on sourcecatalog.ItemCatalogID = sourceitem.ItemCatalogGroupID left join SET_UnitofMeasure on SET_UnitofMeasure.UOMID = INV_Item.PrimaryUOMCode Left JOIN Fabrics_PackType On Fabrics_PackType.PackTypeID=INV_StockTransactionDetail.PackTypeID AND Fabrics_PackType.Status=1 where INV_StockTransactionHeader.Status = 1 and INV_StockTransactionHeader.CompanyID = @CompanyID and INV_StockTransactionHeader.PeriodID = @PeriodID and INV_StockTransactionHeader.StockTransactionID = @StockTransactionID
)as tab

SELECT std.TransactionDetailID,INV_SET_Category.CategoryID as ItemCategoryID, INV_SET_Category.CategoryName, STD.ItemID, INV_Item.Description as ItemDescription, INV_Item.InventoryItemStatusCode ,STD.TransactionUOMID, ISNULL(INV_Item.ListPricePerUnit, 0) AS TransactionCost, INV_StockTransactionHeader.DocumentTypeID, INV_StockTransactionHeader.DocumentNo, STD.TransactionDetailID, STD.IncurredOnID,INV_Item.InventoryItemStatusCode, SET_UnitofMeasure.UOMName, Round(IsNull( ( case isnull(INV_Item.DownloadableFlag,0) when 0 then (select top 1 INV_StockTransactionDetail.NewCost from INV_StockTransactionDetail Inner Join Inv_StockTransactionHeader On Inv_StockTransactionHeader.CompanyID = INV_StockTransactionDetail.CompanyID And Inv_StockTransactionHeader.PeriodID = INV_StockTransactionDetail.PeriodID And Inv_StockTransactionHeader.StockTransactionID = INV_StockTransactionDetail.StockTransactionID Inner Join Set_DocumentType on Set_DocumentType.CompanyID = Inv_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = Inv_StockTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = Inv_StockTransactionHeader.DocumentTypeID Inner Join ApplicationMenu On ApplicationMenu.MenuID = Set_DocumentType.MenuID And ApplicationMenu.MenuPath = '/Inventory/Transaction/Stock_frm.aspx' where INV_StockTransactionDetail.ItemID = INV_Item.ItemID and --INV_StockTransactionDetail.CompanyID = INV_Item.CompanyID and NewCost is not null Order By Inv_StockTransactionHeader.DocumentDate desc) else isnull(inv_Item.ListPricePerUnit,0) end ) , 0) * (STD.TransactionQuantity), 0) AS Amount, INV_StockTransactionHeader.StockTransactionID, ISNULL(STD.Comments, '') as Comments, ISNULL(STD.IsDone, 'false') as IsDone, Abs(STD.PrimaryQuantity) as TransactionQuantity2, Cast(Abs(STD.TransactionQuantity) - Abs(isnull( ( Select Sum(INV_StockTransactionDetail.TransactionQuantity) from INV_StockTransactionDetail Where INV_StockTransactionDetail.CompanyID = @CompanyID And INV_StockTransactionDetail.PeriodID = @PeriodID And INV_StockTransactionDetail.Status = 1 AND INV_StockTransactionDetail.SourceDocumentTypeID = INV_StockTransactionHeader.DocumentTypeID And INV_StockTransactionDetail.SourceCode = INV_StockTransactionHeader.DocumentNo And INV_StockTransactionDetail.SourceHeaderID = STD.StockTransactionID And INV_StockTransactionDetail.SourceLineID = STD.TransactionDetailID ), 0)) AS decimal(18, 0)) as TransactionQuantity, isnull(INV_Item.DownloadableFlag,0) as DownloadableFlag ,CC.CostCenterName as HeaderCCName ,STD.SourceCode ,STD.SourceHeaderID ,STD.SourceLineID FROM INV_StockTransactionHeader inner join INV_StockTransactionDetail STD on STD.StockTransactionID = INV_StockTransactionHeader.StockTransactionID and STD.CompanyID = INV_StockTransactionHeader.CompanyID and STD.PeriodID = INV_StockTransactionHeader.PeriodID INNER JOIN INV_Item ON INV_Item.ItemID = STD.ItemID --AND INV_Item.CompanyID = STD.CompanyID Inner join Set_DocumentType on Set_DocumentType.DocumentTypeID = INV_StockTransactionHeader.DocumentTypeID And Set_DocumentType.CompanyID = INV_StockTransactionHeader.CompanyID And Set_DocumentType.PeriodID = INV_StockTransactionHeader.PeriodID -- AND Set_DocumentType.DocumentType like 'GIN' LEFT JOIN INV_SET_Category ON INV_Item.ItemTypeID = INV_SET_Category.CategoryID --and INV_Item.CompanyID = INV_SET_Category.CompanyID LEFT JOIN [SET_UnitofMeasure] ON [SET_UnitofMeasure].[UOMID] = STD.[TransactionUOMID] LEFT JOIN [SET_Currency] ON [SET_Currency].[CurrencyID] = STD.[CurrencyID] LEFT JOIN [SET_CostCenter] ON [SET_CostCenter].[CostCenterID] = STD.CostCenterID Left JOIN [SET_CostCenter] CC on CC.CostCenterID= INV_StockTransactionHeader.CostCenterID
LEFT JOIN [SET_Project] ON [SET_Project].[ProjectID] = STD.[ProjectID] LEFT JOIN AR_Set_Customer on AR_Set_Customer.CustomerID = [INV_StockTransactionHeader].BusinessPartnerID --AND AR_Set_Customer.CompanyID = INV_StockTransactionHeader.CompanyID AND AR_Set_Customer.PeriodID = INV_StockTransactionHeader.PeriodID
Where STD.Status = 1 ANd STD.CompanyID = @CompanyID ANd STD.PeriodID = @PeriodID AND INV_StockTransactionHeader.StatusCode = 1 --and std.Isdone = 1 {0}
